export interface SuggestionToken {
  text: string;
  value?: string;
}

export type SuggestionExpression =
  | { kind: "atom"; tokens: SuggestionToken[] }
  | { kind: "not"; child: SuggestionExpression }
  | {
      kind: "and" | "or";
      left: SuggestionExpression;
      right: SuggestionExpression;
    };

const STRING_ESCAPES: Record<string, string> = { a: "\x07", b: "\b", f: "\f", n: "\n", r: "\r", t: "\t", v: "\v" };
const BRACKET_PAIRS: Record<string, string> = { "(": ")", "[": "]", "{": "}" };
// Sticky: lastIndex is set before every exec.
const LEXER =
  /\s+|\/\/[^\n]*|"(?:\\[^\r\n]|[^"\\\r\n])*"|'(?:\\[^\r\n]|[^'\\\r\n])*'|[a-zA-Z_]\w*|\d+(?:\.\d+)?|&&|\|\||==|!=|<=|>=|[()[\]{},.!<>+*/%?:-]/gy;

function decodeString(text: string): string {
  return text.slice(1, -1).replace(/\\(u[\da-fA-F]{4}|U[\da-fA-F]{8}|x[\da-fA-F]{2}|[0-7]{3}|.)/g, (_, escaped: string) => {
    if (/^[uUx]/.test(escaped)) return String.fromCodePoint(Number.parseInt(escaped.slice(1), 16));
    if (/^[0-7]{3}$/.test(escaped)) return String.fromCodePoint(Number.parseInt(escaped, 8));
    if (escaped in STRING_ESCAPES) return STRING_ESCAPES[escaped];
    if (["\\", '"', "'", "?"].includes(escaped)) return escaped;
    throw new Error("Unsupported string escape");
  });
}

/**
 * A deliberately small CEL reader, not a filter evaluator. Boolean structure is
 * parsed; calls and other atoms stay opaque for each suggestion provider to interpret.
 * Unsupported syntax never falls back to searching strings for tag-like text.
 */
function parseExpression(source: string): SuggestionExpression {
  const tokens: SuggestionToken[] = [];
  let end = 0;
  while (end < source.length) {
    LEXER.lastIndex = end;
    const match = LEXER.exec(source);
    if (!match) throw new Error("Unsupported token");
    const text = match[0];
    end = LEXER.lastIndex;
    if (/^\s|^\/\//.test(text)) continue;
    tokens.push({ text, value: /^["']/.test(text) ? decodeString(text) : undefined });
  }
  let position = 0;
  const take = (text: string) => {
    if (tokens[position]?.text !== text) return false;
    position++;
    return true;
  };
  const unary = (): SuggestionExpression => {
    if (take("!")) return { kind: "not", child: unary() };
    if (take("(")) {
      const expression = binary("||");
      if (!take(")")) throw new Error("Unbalanced expression");
      return expression;
    }
    const start = position;
    const closers: string[] = [];
    while (position < tokens.length) {
      const token = tokens[position];
      if (token.value === undefined) {
        const text = token.text;
        if (!closers.length && ["&&", "||", ")"].includes(text)) break;
        // Ternaries can change the meaning of the surrounding Boolean clauses.
        if (!closers.length && ["?", ":", ","].includes(text)) throw new Error("Unsupported expression");
        if (text in BRACKET_PAIRS) closers.push(BRACKET_PAIRS[text]);
        else if ([")", "]", "}"].includes(text) && closers.pop() !== text) throw new Error("Unbalanced atom");
      }
      position++;
    }
    if (position === start || closers.length) throw new Error("Incomplete expression");
    const atom = tokens.slice(start, position);
    if (/^(?:in|[.!<>=+*/%-]|==|!=|<=|>=)$/.test(atom.at(-1)?.text ?? "")) throw new Error("Incomplete atom");
    return { kind: "atom", tokens: atom };
  };
  const binary = (operator: "&&" | "||"): SuggestionExpression => {
    const next = () => (operator === "&&" ? unary() : binary("&&"));
    let expression = next();
    while (take(operator)) expression = { kind: operator === "&&" ? "and" : "or", left: expression, right: next() };
    return expression;
  };
  const expression = binary("||");
  if (position !== tokens.length) throw new Error("Unsupported expression suffix");
  return expression;
}

/** Invalid or unsupported syntax contributes no inferred conditions. */
export function parseSuggestionExpression(source: string): SuggestionExpression | undefined {
  try {
    return parseExpression(source);
  } catch {
    return undefined;
  }
}

/** Read a complete list of string literals, allowing CEL's trailing comma. */
export function readStringList(tokens: SuggestionToken[]): string[] | undefined {
  if (tokens[0]?.text !== "[" || tokens.at(-1)?.text !== "]") return undefined;
  const values = tokens.slice(1, -1);
  if (values.at(-1)?.text === ",") values.pop();
  if (!values.length) return [];
  if (values.length % 2 === 0) return undefined;
  if (values.some((token, index) => (index % 2 === 0 ? token.value === undefined : token.text !== ","))) return undefined;
  return values.filter((_, index) => index % 2 === 0).map((token) => token.value as string);
}

import { describe, expect, it } from "vitest";
import { getMemoSuggestions } from "@/lib/memo-suggestions";
import { extractTagConditions } from "@/lib/tag-suggestions";

describe("tag suggestion extraction", () => {
  it.each([
    ['"work" in tags', ["work"]],
    ["'work/project' in tags", ["work/project"]],
    ['tag in ["work", "release",]', ["work", "release"]],
    ['("work" in tags && "release" in tags) || "personal" in tags', ["work", "release", "personal"]],
    ['has_task_list && "work" in tags && content.contains("release")', ["work"]],
    ['"work" in tags // ignore this: && !("work" in tags)', ["work"]],
    ['"\\u5de5\\u4f5c" in tags', ["工作"]],
    ["'it\\'s' in tags", ["it's"]],
    ['!("archived" in tags)', []],
    ['!("archived" in tags || "private" in tags)', []],
    ['!("archived" in tags && !("work" in tags))', ["work"]],
    ['content.contains("work")', []],
    ["content.contains('\"work\" in tags')", []],
    ['tags.exists(t, t.startsWith("work/"))', []],
    ['("work" in tags) == false', []],
    ['true ? "work" in tags : "personal" in tags', []],
    ['"work" in tags &&', []],
    ['"work" in tags && visibility ==', []],
    ['("work" in tags', []],
    ['"work" in tags || content.contains("x"', []],
    ['"work" in tags && x[)', []],
    ['"work" in tags && @', []],
    ['tag in ["work", variable]', []],
    ["tag in []", []],
  ])("extracts explicit tags conservatively: %s", (source, expected) => {
    expect(extractTagConditions(source).candidates).toEqual(expected);
  });

  it("combines unconditional exclusions without treating an OR branch as a global exclusion", () => {
    expect([...extractTagConditions('!("work" in tags) && !("personal" in tags)').excluded]).toEqual(["work", "personal"]);
    expect([...extractTagConditions('!("work" in tags) || "personal" in tags').excluded]).toEqual([]);
    expect([...extractTagConditions('!("work" in tags) || (!("work" in tags) && has_task_list)').excluded]).toEqual(["work"]);
    expect([...extractTagConditions('!(tag in ["work", "personal"])').excluded]).toEqual(["work", "personal"]);
    expect([...extractTagConditions('!("work" in tags && "personal" in tags)').excluded]).toEqual([]);
  });
});

describe("memo suggestions", () => {
  it("ranks selection before search before View, deduplicates, and leaves the visible limit to the editor", () => {
    const suggestions = getMemoSuggestions(
      [
        { factor: "celSearch", value: 'tag in ["search", "selected"]' },
        { factor: "tagSearch", value: "selected" },
        { factor: "tagSearch", value: "second" },
      ],
      'tag in ["view", "search", "selected"]',
    );
    expect(suggestions.map(({ id, source }) => [id, source])).toEqual([
      ["tag:selected", "selection"],
      ["tag:second", "selection"],
      ["tag:search", "search"],
      ["tag:view", "view"],
    ]);
    expect(suggestions[0]).toMatchObject({ kind: "tag", tag: "selected" });
  });

  it("applies exclusions across sources and ignores plain-text searches", () => {
    expect(
      getMemoSuggestions(
        [
          { factor: "tagSearch", value: "archived" },
          { factor: "celSearch", value: '!("work" in tags)' },
          { factor: "contentSearch", value: "#personal" },
        ],
        '!("archived" in tags) && tag in ["work", "release"]',
      ).map((suggestion) => suggestion.id),
    ).toEqual(["tag:release"]);
  });

  it("does not exclude a selected tag merely because one alternative negates it", () => {
    expect(
      getMemoSuggestions([{ factor: "tagSearch", value: "work" }], '!("work" in tags) || "personal" in tags').map(
        (suggestion) => suggestion.id,
      ),
    ).toEqual(["tag:work", "tag:personal"]);
  });

  it("validates complete tag identities and preserves case, Unicode, punctuation, and paths", () => {
    const tags = ["work/project", "工作", "🎉", "C++", "R&D", "Work", "work", "", "two words", "#work", "work/", "x\ny", "wo\u200brk"];
    expect(getMemoSuggestions(tags.map((value) => ({ factor: "tagSearch", value }))).map((suggestion) => suggestion.id)).toEqual(
      tags.slice(0, 7).map((tag) => `tag:${tag}`),
    );
